// Country and city lists generated by scripts/build-geo.mjs (data © GeoNames, CC BY 4.0).
// Loaded on demand and cached for the session.
let countriesPromise = null;
const cityCache = new Map();

export function loadCountries() {
  if (!countriesPromise) {
    countriesPromise = fetch('/geo/countries.json').then((r) => { if (!r.ok) throw new Error('Could not load countries.'); return r.json(); })
      .catch((e) => { countriesPromise = null; throw e; });
  }
  return countriesPromise;
}

// A country's provinces or states, each with its own cities. Empty when the data has none.
const regionCache = new Map();
export function loadRegions(code) {
  if (!code) return Promise.resolve([]);
  if (!regionCache.has(code)) {
    regionCache.set(code, fetch(`/geo/regions/${code}.json`).then((r) => (r.ok && (r.headers.get('content-type') || '').includes('json') ? r.json() : [])).catch(() => { regionCache.delete(code); return []; }));
  }
  return regionCache.get(code);
}

export function loadCities(code) {
  if (!code) return Promise.resolve([]);
  if (!cityCache.has(code)) {
    cityCache.set(code, fetch(`/geo/cities/${code}.json`).then((r) => (r.ok ? r.json() : [])).catch(() => { cityCache.delete(code); return []; }));
  }
  return cityCache.get(code);
}
